interface StockLevelBadgeProps {
  current: number
  min: number
  className?: string
}

export function StockLevelBadge({ current, min, className }: StockLevelBadgeProps) {
  const showsMin = min > 0
  const isAtOrBelowMin = showsMin && current <= min
  const isApproaching = showsMin && !isAtOrBelowMin && current <= min * 1.25

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums',
        isAtOrBelowMin && 'bg-[color:var(--color-rust)] text-[color:var(--color-bone)]',
        isApproaching && 'border border-[color:var(--color-rust)] text-[color:var(--color-rust)] bg-transparent',
        !isAtOrBelowMin && !isApproaching && 'border border-stone-brand/40 text-foreground bg-transparent',
        className,
      )}
    >
      {showsMin ? `${current} / min ${min}` : current}
    </span>
  )
}

