const url = new URL(request.url)
const category = url.searchParams.get('category')
const supplier_id = url.searchParams.get('supplier_id')
const stock_status = url.searchParams.get('stock_status')
const location_id = url.searchParams.get('location_id')
const is_active = url.searchParams.get('is_active') !== 'false'
const include = url.searchParams.get('include') // e.g. 'ink_registry'
const sort = url.searchParams.get('sort') // e.g. 'value'
const min_threshold_raw = url.searchParams.get('min_threshold')
const limit_raw = url.searchParams.get('limit')
const limit = limit_raw ? parseInt(limit_raw, 10) : undefined

// Build select — conditionally include ink_registry join
const selectCols = include?.includes('ink_registry')
  ? '*, suppliers(id, name), locations(id, name), studio_ink_registry!studio_ink_registry_item_id_fkey(id, batch_number, manufacture_date, expiry_date, reach_compliant, sds_url, product_code)'
  : '*, suppliers(id, name), locations(id, name)'

let query = supabase
  .from('inventory_items')
  .select(selectCols)
  .eq('studio_id', member.studio_id)
  .eq('is_active', is_active)

if (sort === 'value') {
  // Sort by total value = cost_per_unit_cents * current_stock descending
  query = query.order('cost_per_unit_cents', { ascending: false })
} else {
  query = query.order('name')
}

if (category) query = query.eq('category', category as 'ink' | 'needle' | 'supply' | 'aftercare' | 'equipment' | 'apparel' | 'other')
if (supplier_id) query = query.eq('supplier_id', supplier_id)
if (location_id) query = query.eq('location_id', location_id)
// min_threshold=0 means "items where min_threshold = 0" (for BulkThresholdsDrawer)
if (min_threshold_raw !== null) {
  const min_threshold_val = parseInt(min_threshold_raw, 10)
  query = query.eq('min_threshold', min_threshold_val)
}
if (limit) query = (query as Parameters<typeof query.limit>[0] extends never ? typeof query : typeof query).limit(limit)

const { data, error } = await query

if (error) {
  logger.error({ err: error }, 'inventory items GET failed')
  return Response.json({ error: 'Failed to fetch items' }, { status: 500 })
}

let items = data ?? []

if (stock_status === 'low') {
  items = items.filter(
    (i) => i.current_stock > 0 && i.current_stock <= i.min_threshold,
  )
} else if (stock_status === 'out') {
  items = items.filter((i) => i.current_stock <= 0)
}

// Client-side sort by total value when sort=value (DB sort by cost only, not computed column)
if (sort === 'value') {
  items = [...items].sort(
    (a, b) =>
      Number(b.cost_per_unit_cents ?? 0) * Number(b.current_stock) -
      Number(a.cost_per_unit_cents ?? 0) * Number(a.current_stock),
  )
}

return Response.json({ data: items })
